def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        # Expanding V, truncated at board edges
        if r <= center:
            for c in (center-r, center+r):
                if 0 <= c < n:
                    out[r][c] = 2
        # Diagonal stripes, period four; omit positions inside the V
        for c in range(n):
            if c % 4 == (r + 2) % 4 and (r > center or abs(c-center) < r):
                out[r][c] = 1
    return out

